        <tr>
          <th>Name</th>
          <th>Email</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {visible.map((client) => (
          <tr key={client.id} data-testid={`client-row-${client.id}`}>
            <td data-testid="client-name">{client.name}</td>
            <td data-testid="client-email">{client.email}</td>
            <td>
              <Link
                to="/clients/$clientId"
                params={{ clientId: String(client.id) }}
                data-testid={`client-open-${client.id}`}
              >
                Open
              </Link>
            </td>
          </tr>
        ))}
        </tbody>
      </table>
    </>
  );
}
